<script setup lang="ts">import{Head,useForm}from'@inertiajs/vue3';const form=useForm({current_password:'',password:'',password_confirmation:''});const submit=()=>form.put('/ganti-password',{onFinish:()=>form.reset()});</script>
<template><Head title="Ganti Kata Sandi"/><main class="password-page"><form class="password-card" @submit.prevent="submit"><div class="shield">✓</div><div><p class="eyebrow">Keamanan akun</p><h1>Ganti kata sandi</h1><p>Gunakan minimal 10 karakter dengan huruf besar, huruf kecil, dan angka.</p></div><label>Kata sandi saat ini<input v-model="form.current_password" type="password" autocomplete="current-password" required/><small v-if="form.errors.current_password">{{form.errors.current_password}}</small></label><label>Kata sandi baru<input v-model="form.password" type="password" autocomplete="new-password" required/><small v-if="form.errors.password">{{form.errors.password}}</small></label><label>Konfirmasi kata sandi<input v-model="form.password_confirmation" type="password" autocomplete="new-password" required/></label><button class="primary-button" :disabled="form.processing">{{form.processing?'Menyimpan…':'Simpan dan lanjutkan'}}</button></form></main></template>
<style scoped>.password-page{min-height:100vh;display:grid;place-items:center;padding:1.5rem;background:#f4f7fb}.password-card{width:min(460px,100%);display:grid;gap:1.1rem;padding:2rem;border:1px solid #dbe3ee;border-radius:1.2rem;background:#fff;box-shadow:0 20px 60px rgb(15 23 42/.08)}.shield{width:3rem;height:3rem;display:grid;place-items:center;border-radius:.8rem;background:#eef2ff;color:#4338ca;font-weight:900}.password-card h1{font-size:1.5rem;font-weight:850;color:#0f172a}.password-card p{color:#64748b}.password-card label{display:grid;gap:.4rem;color:#334155;font-size:.8rem;font-weight:750}.password-card input{padding:.7rem;border:1px solid #cbd5e1;border-radius:.65rem}.password-card small{color:#dc2626}</style>
